  if(!mapCtx||!mapCanvas)return;const w=mapCanvas.width,h=mapCanvas.height,cx=w/2,cy=h/2;mapCtx.clearRect(0,0,w,h);mapCtx.fillStyle='#1f2c2a';mapCtx.fillRect(0,0,w,h);
